setup:
CREATE TABLE coastlines AS SELECT * FROM (VALUES
  ('North Coast', ST_GeomFromText('LINESTRING(0 0, 1 0.1, 2 0.05, 3 0.15, 4 0.0, 10 0)')),
  ('South Cove',  ST_GeomFromText('LINESTRING(0 0, 1 2, 2 0.1, 5 1.9, 10 0)'))
) t(segment_name, geom);

solution:
LOAD spatial;

SELECT segment_name,
       ST_NPoints(geom) AS points_before,
       ST_NPoints(ST_Simplify(geom, 1.8)) AS points_after
FROM coastlines
ORDER BY segment_name;
